-- PT106-S3-Q23. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT106-S3-Q23$batch09$ AND q.stimulus=$batch09$Ethicist: It is widely believed that it is always wrong to tell lies, but this is a rule almost no one fully complies with. In fact, lying is often the morally appropriate thing to do. It is morally correct to lie when telling the truth carries the reasonable expectation of producing considerable physical or psychological harm to others.$batch09$ AND q.prompt=$batch09$Which one of the following most closely conforms to the principle the ethicist endorses?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT106-S3-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT106-S3-Q23$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S3-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT106-S3-Q23$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$If telling the truth carries a reasonable expectation of considerable physical or psychological harm to others, it is morally correct to lie.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Three things have to be true. The truth must cause harm, the harm must be considerable, and it must fall on someone other than the liar. Missing a dull movie or an awkward chat doesn't count.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A lie told because the truth would considerably hurt someone else.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT106-S3-Q23$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Juan would miss an "aesthetically pleasing experience." Missing a good film isn't considerable physical or psychological harm.$batch09$), ($batch09$B$batch09$, $batch09$The father lies to dodge a discussion. An argument about candidates isn't the harm the rule requires.$batch09$), ($batch09$C$batch09$, $batch09$The husband lies to avoid inconvenience. If anyone is at risk, it's the husband, who recently had severe chest pains. The lie creates danger rather than preventing harm to others.$batch09$), ($batch09$D$batch09$, $batch09$Hearing that the mother loves the older sister more would plausibly cause the boy serious psychological harm. That harm falls on someone other than the liar. So the lie fits the rule.$batch09$), ($batch09$E$batch09$, $batch09$This is the trap, picked by 12%. Jamal does face emotional pain, and that looks like the rule's psychological harm. But the rule protects others. Jamal lies to avoid personal pain and embarrassment. Read the rule's last two words carefully: "to others."$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT106-S3-Q23$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
